mapper.select:
SELECT *,  FROM ai_agent_run
WHERE workspace_id = #{workspaceId} AND id = #{id}
FOR UPDATE

SELECT * FROM ai_agent_segment
WHERE workspace_id = #{workspaceId} AND id = #{id}
FOR UPDATE

SELECT *,  FROM ai_agent_run
WHERE workspace_id = #{workspaceId} AND owner_user_id = #{ownerUserId}
  AND client_request_key = #{clientRequestKey}

SELECT *,  FROM ai_agent_run
WHERE workspace_id = #{workspaceId} AND organization_privacy_generation = #{organizationPrivacyGeneration} AND owner_user_id = #{ownerUserId}
AND session_id = #{sessionId}
AND status = #{state}
AND id < #{beforeId}
ORDER BY id DESC LIMIT #{limit}

SELECT *,  FROM ai_agent_run
WHERE workspace_id = #{workspaceId}
  AND status IN ('queued', 'running', 'paused', 'waiting_approval')
  AND execution_deadline_at <= CURRENT_TIMESTAMP(6)
ORDER BY execution_deadline_at, id LIMIT #{limit}

SELECT COUNT(*) FROM ai_agent_run
WHERE workspace_id = #{workspaceId} AND session_id = #{sessionId}
  AND status IN ('queued', 'running', 'waiting_approval', 'paused')

mapper.update:
UPDATE ai_agent_segment
SET known_steps = #{segment.knownSteps},
    known_input_tokens = #{segment.knownInputTokens},
    known_output_tokens = #{segment.knownOutputTokens},
    usage_uncertain = #{segment.usageUncertain},
    status = #{segment.status,jdbcType=VARCHAR},
    failure_reason = #{segment.failureReason,jdbcType=VARCHAR},
    started_at = #{segment.startedAt,jdbcType=TIMESTAMP},
    settled_at = #{segment.settledAt,jdbcType=TIMESTAMP}
WHERE workspace_id = #{segment.workspaceId} AND id = #{segment.id}
  AND status = #{expectedStatus}
  AND run_id = #{segment.runId}
  AND execution_generation = #{segment.executionGeneration}

mapper.select:
SELECT * FROM ai_agent_segment
WHERE workspace_id = #{workspaceId} AND run_id = #{runId}
ORDER BY segment_no, attempt_no

mapper.update:
UPDATE ai_agent_segment SET turn_id = NULL
WHERE workspace_id = #{workspaceId} AND run_id = #{runId}
  AND status NOT IN ('claimed', 'running')

mapper.delete:
DELETE FROM ai_agent_segment
WHERE workspace_id = #{workspaceId} AND run_id = #{runId}
  AND status NOT IN ('claimed', 'running')

mapper.update:
UPDATE ai_agent_run SET owner_user_id = NULL
WHERE workspace_id = #{workspaceId} AND owner_user_id = #{ownerUserId}
  AND purged_at IS NOT NULL

mapper.select:
SELECT id FROM ai_agent_run
WHERE workspace_id = #{workspaceId} AND owner_user_id = #{ownerUserId}
  AND id > #{afterId}
ORDER BY id LIMIT #{limit}

SELECT DISTINCT owner_user_id FROM ai_agent_run
WHERE workspace_id = #{workspaceId} AND purged_at IS NOT NULL AND owner_user_id > #{afterOwnerId}
ORDER BY owner_user_id LIMIT #{limit}

SELECT COUNT(*) FROM ai_agent_run
WHERE workspace_id = #{workspaceId} AND owner_user_id = #{ownerUserId}
  AND status IN ('queued', 'running', 'waiting_approval', 'paused')

SELECT *,  FROM ai_agent_run
WHERE workspace_id = #{workspaceId} AND id > #{afterId}
  AND status IN ('queued', 'running', 'waiting_approval', 'paused')
ORDER BY id LIMIT #{limit}

mapper.update:
UPDATE ai_agent_run
SET plan_schema_version = #{run.planSchemaVersion,jdbcType=SMALLINT},
    plan_revision = #{run.planRevision},
    plan_json = CONVERT(#{run.planJson,jdbcType=VARBINARY,typeHandler=ooo.klae.connex.backend.mappers.AiIdentifierUtf8TextTypeHandler} USING utf8mb4),
    checkpoint_schema_version = #{run.checkpointSchemaVersion,jdbcType=SMALLINT},
    checkpoint_revision = #{run.checkpointRevision},
    checkpoint_json = CONVERT(#{run.checkpointJson,jdbcType=VARBINARY,typeHandler=ooo.klae.connex.backend.mappers.AiIdentifierUtf8TextTypeHandler} USING utf8mb4),
    memory_schema_version = #{run.memorySchemaVersion,jdbcType=SMALLINT},
    memory_json = CONVERT(#{run.memoryJson,jdbcType=VARBINARY,typeHandler=ooo.klae.connex.backend.mappers.AiIdentifierUtf8TextTypeHandler} USING utf8mb4),
    last_committed_segment_no = #{run.lastCommittedSegmentNo},
    state_version = #{run.stateVersion}
WHERE workspace_id = #{run.workspaceId} AND id = #{run.id}
  AND state_version = #{expectedStateVersion} AND execution_generation = #{expectedExecutionGeneration}
  AND runtime_contract_version = 2 AND active_segment_id <=> #{expectedActiveSegmentId,jdbcType=INTEGER}
  AND plan_revision = #{expectedPlanRevision} AND checkpoint_revision = #{expectedCheckpointRevision}

mapper.select:
SELECT id, workspace_id, session_id, seq, privacy_generation, organization_privacy_generation, mission_run_id, mission_message_kind
FROM ai_chat_message WHERE workspace_id = #{workspaceId} AND mission_run_id = #{runId}
  AND mission_message_kind = 'goal'

SELECT *, CAST(arguments_json AS BINARY) AS utf8_arguments_json,
       CAST(result_json AS BINARY) AS utf8_result_json FROM ai_chat_tool_call
WHERE workspace_id = #{workspaceId} AND mission_run_id = #{runId}
  AND artifact_origin = 'mission' AND idempotency_key = #{idempotencyKey}
FOR UPDATE
